```bash
# a caller that closed stderr, rather than redirecting it to /dev/null, makes the `>&2` fail; zsh cannot report that, so it aborts the script, which only a subshell contains, and `|| return 0` keeps the status from the caller
nvm_err() {
  (>&2 nvm_echo "$@") || return 0
}
