function _git_fork {
  local i c=2 flags="--no-remote --remote-name --org"
  while [ $c -lt $cword ]; do
    i="${words[c]}"
    case "$i" in
    --org)
      ((c++))
      flags=${flags/$i/}
      ;;
    --remote-name)
      ((c++))
      flags=${flags/$i/}
      flags=${flags/--no-remote/}
      ;;
    --no-remote)
      flags=${flags/$i/}
      flags=${flags/--remote-name/}
      ;;
    esac
    ((c++))
  done
  case "$prev" in
  --remote-name|--org)
    COMPREPLY=()
    ;;
  *)
    __gitcomp "$flags"
    ;;
  esac
}
